  const clip = (t) => `<div style="max-width:280px;max-height:4.8em;overflow:auto;white-space:normal;font-size:12.5px" title="${esc(t)}">${esc(t)}</div>`;
  const lastBody = () => { const o = [...document.querySelectorAll('.ov')].pop(); return o && o.querySelector('.body'); };

  /* ---------- SLA ---------- */
  function calcDue(r) { const s = H().cfg.sla[r.priority] || { respond: 8, resolve: 24 }; const t = new Date(r.created).getTime(); r.respondBy = new Date(t + s.respond * 36e5).toISOString(); r.dueBy = new Date(t + s.resolve * 36e5 + (r.heldMs || 0)).toISOString(); }
